<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Every Child Deserves to Learn - Infographic</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      background-color: #ffffff; /* ensure white background for screenshot */
    }
    #container {
      width: 100%;
      height: 100%;
    }
  </style>
</head>
<body>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const dsl = `
infographic list-waterfall-badge-card
data
  title 250 MILLION CHILDREN OUT OF SCHOOL
  desc The Global Education Crisis: 70% of children in low/middle-income countries cannot read by age 10. We must act now to overcome the key barriers.
  lists
    - label Conflict & Emergencies
      desc Schools destroyed; girls 2.5× more likely to be excluded in crises.
      icon warning
    - label Poverty & Labour
      desc Families cannot afford fees, forcing children to work.
      icon bill
    - label Gender Inequality
      desc Social norms limit girls' access, especially at secondary levels.
      icon female
    - label Disability
      desc ~49% of children with disabilities in low-income countries excluded.
      icon user delete
    - label Climate Shocks
      desc Floods and droughts increasingly disrupt schooling and safety.
      icon thunderbolt
    - label What Can Be Done
      desc Invest in peace, inclusive education, and innovation. No child left behind.
      icon heart
theme
  palette #00a9ce #ff7f41 #ffb81c
`;
    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '100%',
      height: '100%',
    });

    // We wait for fonts to load then render
    document.fonts?.ready.then(() => {
      infographic.render(dsl);
      // add a small delay to ensure rendering completes before playwright takes a screenshot
      setTimeout(() => {
        window.__INFOGRAPHIC_READY__ = true;
      }, 500);
    }).catch((error) => {
      console.error('Error waiting for fonts:', error);
      infographic.render(dsl);
      window.__INFOGRAPHIC_READY__ = true;
    });
  </script>
</body>
</html>

